public display TFMDocumentQueueStatus status()
{
    TFMDocumentQueueStatus  ret = this.DocuRefRecId ? TFMDocumentQueueStatus::Completed : TFMDocumentQueueStatus::ReadyForProcessing;

    return ret;
}

public display Description255 whereItPoints()
{
    Description255  ret = new DictTable(this.RefTableID).label();
    MapEnumerator   keyFields = TFMHelper::getPrimaryKeysFromTableName(tableId2Name(this.RefTableID)).getEnumerator();
    Common          common = new DictTable(this.refTableID).makeRecord();
    DictField       dictField;

    select firstonly common where common.RecId == this.refrecID;

    while (keyFields.moveNext())
    {
        dictField = keyFields.currentValue();
        ret += ', ' + dictField.label() + ' ' + strFmt('%1',common.(dictField.id()));
    }

    return ret;
}

/// <summary>
///
/// </summary>
public static void Add2Queue(Common _referencedBuffer, TFMMediaID _mediaID, str _comment, TFMDocumentDeviceId _deviceID)
{
    TFMMediaQueue queue;

    queue.RefRecId = _referencedBuffer.RecId;
    queue.RefTableId = _referencedBuffer.TableID;
    queue.DeviceId = _deviceID;
    queue.MediaID = _mediaID;
    queue.Note = _comment;
    queue.insert();
}

public static void AddMap2Queue(Common _referencedBuffer, Map _mediaIDs, TFMDocumentDeviceId _deviceID)
{
    MapEnumerator mEnum = _mediaIDs.getEnumerator();

    while(mEnum.moveNext())
    {
        TFMMediaQueue::Add2Queue(_referencedBuffer,mEnum.currentKey(), mEnum.currentValue(),_deviceID);
    }
}

public static Map separateIDsAndComments(str _mediaIDs)
{
    List            mediaIDs = strSplit(_mediaIDs,'§');
    ListEnumerator  mediaEnum = mediaIDs.getEnumerator();
    Map             returnMap = new Map(Types::String, Types::String);
    TFMMediaID      mediaID;
    str             comment;

    while (mediaEnum.moveNext())
    {
        mediaID = subStr(mediaEnum.current(),1,strscan(mediaEnum.current(),';',1,strLen(mediaEnum.current()))-1);
        comment = subStr(mediaEnum.current(),strscan(mediaEnum.current(),';',1,strLen(mediaEnum.current()))+1,strLen(mediaEnum.current()));
        returnMap.insert(mediaID,comment);
    }

    return returnMap;
}

public static TFMMediaQueue Find(TFMMediaID _mediaID, TFMDocumentDeviceId _deviceID, boolean _select4Update = false)
{
    TFMMediaQueue   queue;

    queue.selectForUpdate(_select4Update);

    select firstonly queue where queue.mediaID == _mediaID && (queue.deviceId == _deviceID || queue.DeviceId == '*');

    return queue;
}

public static TFMMediaQueue FindByMediaId(TFMMediaID _mediaID)
{
    TFMMediaQueue   queue;
    queue.selectForUpdate(false);
    select firstonly queue where queue.mediaID == _mediaID;
    return queue;
}

