/// <summary>
///
/// </summary>
public str getImageHtml(int height = 0)
{
    #tfm
    DocuRef docuRef;
    System.IO.Stream        attachStream;
    System.Drawing.Image    image;
    docuRef = DocuRef::findRecId(this.DocuRefRecId);
    TFMMediaProvider mediaProvider = TFMMediaProvider::instance();
    if (!docuRef)
    {
        return '';
    }

    #ifnot.isAX6

    if(!mediaProvider.getMedia(docuRef.Name))
    {
        attachStream = DocumentManagement::getAttachmentStream(docuRef);
        image = System.Drawing.Image::FromStream(attachStream);
        str base64 = TFMImageHelper::Image2Base64(image);
        mediaProvider.setMedia(docuRef.Name, base64, null);
    } 

    str base64Url = mediaProvider.getMedia(docuRef.Name).getBase64ForHtml();

    if(height)
    {
        return '<img onmouseover="this.style.cursor=\'pointer\'" onmouseout="this.style.cursor=\'default\'" src="'+base64Url+'" alt="'+docuRef.Name+'" height="'+ int2Str(height) +' style="cursor:pointer !important; width:180px;" onclick="const w=window.open(); w.document.write(\'<img src=&quot;\' + this.src + \'&quot; style=&quot;max-width:100%;&quot;>\');" />';
    }

    // the image height and width is requested later.
    if(!image)
    {
        attachStream = DocumentManagement::getAttachmentStream(docuRef);
        image = System.Drawing.Image::FromStream(attachStream);
    }
    return '<img src="'+base64Url+'" alt="'+docuRef.Name+'" height="'+int2Str(real2int(image.Height * 0.25))+'" width="'+int2Str(real2int(image.Width * 0.25))+'">';

    #endif
    #if.isAX6
    image = TFMHelper::getAttachmentAsImage(docuRef);
    return '<img src="data:image/png;base64,'+TFMHelper::Image2Base64(image)+'" alt="Red dot" />';
    #endif
}
